#define main existing_native_main
#include "native_instrument.cpp"
#undef main
int main(int argc,char**argv){if(argc<3)return 2;try{re::Json cat;std::ifstream(argv[2])>>cat;re::Core c("",0,argv[1]);ready(c);if(c.count()!=179)throw std::runtime_error("Schema");unsigned pads=0;double maximum=0;for(int kit=argc>3?std::atoi(argv[3]):0;kit<(argc>3?std::atoi(argv[3])+1:int(cat["kits"].size()));kit++){c.set(1,0);c.set(22,kit/float(cat["kits"].size()-1));ready(c);double peak=0;for(int pad=0;pad<16;pad++){c.set(27,1);float l[128]{},r[128]{};c.render(l,r,128);c.midi(0x90,60+pad,127);double energy=0;for(int b=0;b<140;b++){c.render(l,r,128);for(int n=0;n<128;n++){if(!std::isfinite(l[n])||!std::isfinite(r[n]))throw std::runtime_error("Nonfinite");peak=std::max(peak,double(std::max(std::abs(l[n]),std::abs(r[n]))));energy+=l[n]*l[n]+r[n]*r[n];}}c.midi(0x80,60+pad,0);if(energy<1e-10)throw std::runtime_error("Silent kit pad "+std::to_string(kit)+":"+std::to_string(pad));pads++;}
 c.set(27,1);float l[128]{},r[128]{};c.render(l,r,128);for(int pad=0;pad<16;pad++)c.midi(0x90,60+pad,127);for(int b=0;b<350;b++){c.render(l,r,128);for(int n=0;n<128;n++)peak=std::max(peak,double(std::max(std::abs(l[n]),std::abs(r[n]))));}if(peak>.921)throw std::runtime_error("Peak ceiling exceeded");maximum=std::max(maximum,peak);auto saved=c.state();auto before=extra(c)["graph"];c.set(22,(kit+1)%36/35.f);ready(c);c.restore(saved);ready(c);if(before!=extra(c)["graph"]){std::cerr<<"RESTORE_DIFF "<<re::Json::diff(before,extra(c)["graph"]).dump()<<std::endl;throw std::runtime_error("Kit mix restore "+std::to_string(kit));}std::cout<<re::Json{{"kit",cat["kits"][kit]["name"]},{"pads",16},{"peak",peak},{"state","PASS"}}.dump()<<std::endl;
 }std::cout<<"KIT_MIX_PASS kits="<<(argc>3?1:36)<<" pads="<<pads<<" peak="<<maximum<<" silence=0 state=PASS"<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
